def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    danger_bids = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                    danger_bids.append(float(bid))

    if not alive_opps:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    danger_prev = max(danger_bids) if danger_bids else highest_prev

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 0.55
    elif hp <= 4:
        urgency += 0.3
    if no_water_days >= 2:
        urgency += 0.35
    elif no_water_days >= 1:
        urgency += 0.18
    if day >= 8:
        urgency += 0.08

    if supply >= 22:
        base = 18.0 + 8.0 * urgency
        if highest_prev > 0:
            bid = min(base, avg_prev * 0.72)
        else:
            bid = base
    elif supply >= 19:
        base = 28.0 + 12.0 * scarcity + 10.0 * urgency
        if highest_prev >= 95:
            bid = max(base, min(highest_prev * 0.78, 72.0 + 10.0 * urgency))
        elif highest_prev >= 60:
            bid = max(base, highest_prev * 0.88 + 1.0)
        else:
            bid = max(base, 36.0)
    else:
        base = 42.0 + 18.0 * scarcity + 14.0 * urgency
        if danger_prev >= 100:
            bid = max(base, min(danger_prev * 0.94 + 1.0, 98.0 + 12.0 * urgency))
        elif highest_prev >= 75:
            bid = max(base, highest_prev * 0.96 + 1.5)
        elif highest_prev > 0:
            bid = max(base, highest_prev + 2.0)
        else:
            bid = base

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, 82.0)
    elif hp <= 4 or no_water_days >= 1:
        bid = max(bid, 60.0)

    reserve = 0.0
    if day <= 7:
        reserve = 18.0 * (10 - day)
    elif day <= 9:
        reserve = 10.0 * (10 - day)

    affordable = max(0.0, budget - reserve)
    if affordable <= 0:
        affordable = budget * 0.55

    bid = min(bid, budget, max(0.0, affordable))

    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 140
    WATER_REQ = 8
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return float(min(my_status['budget'], 20.0))
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 80.0
    target_bid = min(my_status['budget'], max(avg_prev_bid + 5.0, 95.0))
    if my_status['hp'] < 4:
        target_bid = min(my_status['budget'], 138.0)
    return float(target_bid)
